(function () {
'use strict';
var buttons = document.querySelectorAll('[data-pwa-install]');
var installed = window.matchMedia('(display-mode: standalone)').matches ||
window.matchMedia('(display-mode: window-controls-overlay)').matches ||
window.navigator.standalone === true;
if ('serviceWorker' in navigator && window.isSecureContext) {
window.addEventListener('load', function () {
navigator.serviceWorker.register('sw.js', { scope: './' }).catch(function () { /* installation manuelle encore possible */ });
});
}
if (!buttons.length || installed) return;   // déjà ouvert comme application : rien à proposer
buttons.forEach(function (b) { b.hidden = false; });
var deferred = null;   // fenêtre d'installation fournie par Chrome / Edge
window.addEventListener('beforeinstallprompt', function (e) {
e.preventDefault();
deferred = e;
});
window.addEventListener('appinstalled', function () {
deferred = null;
buttons.forEach(function (b) { b.hidden = true; });
showDialog('Application installée', ['<strong>GTC Dashboard</strong> est maintenant installé : ouvrez-le depuis votre bureau, le menu Démarrer, le Launchpad ou l\'écran d\'accueil.'], true);
});
var ua = navigator.userAgent;
var isIOS = /iPad|iPhone|iPod/.test(ua) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
var isAndroid = /Android/i.test(ua);
var isMac = /Macintosh|Mac OS X/.test(ua) && !isIOS;
var isEdge = /Edg(e|A|iOS)?\//.test(ua);
var isSamsung = /SamsungBrowser/.test(ua);
var isFirefox = /Firefox|FxiOS/.test(ua);
var isChrome = /Chrome|CriOS/.test(ua) && !isEdge && !isSamsung;
var isSafari = /Safari/.test(ua) && !isChrome && !isEdge && !isFirefox && !/CriOS|FxiOS|EdgiOS/.test(ua);
var SHARE = '<span class="pwa-key"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><path d="m16 6-4-4-4 4"/><path d="M12 2v13"/></svg> Partager</span>';
var steps = function () {
if (!window.isSecureContext) {
return ['L\'installation nécessite une connexion sécurisée : ouvrez le Dashboard à son adresse <strong>https://</strong>.'];
}
if (isIOS) {
return isSafari
? ['Touchez le bouton ' + SHARE + ' en bas de l\'écran (en haut sur iPad).',
'Faites défiler puis touchez <strong>« Sur l\'écran d\'accueil »</strong>.',
'Touchez <strong>« Ajouter »</strong> : l\'icône <strong>GTC Dashboard</strong> apparaît sur l\'écran d\'accueil.']
: ['Touchez le bouton ' + SHARE + ' de votre navigateur (en haut à droite ou dans le menu).',
'Choisissez <strong>« Sur l\'écran d\'accueil »</strong>, puis <strong>« Ajouter »</strong>.',
'Option absente ? Ouvrez cette page dans <strong>Safari</strong> et recommencez.'];
}
if (isAndroid) {
if (isSamsung) return ['Touchez le menu <span class="pwa-key">≡</span> en bas à droite.', 'Choisissez <strong>« Ajouter la page à »</strong> puis <strong>« Écran d\'accueil »</strong>.'];
if (isFirefox) return ['Touchez le menu <span class="pwa-key">⋮</span>.', 'Choisissez <strong>« Installer »</strong> (ou « Ajouter à l\'écran d\'accueil »).'];
return ['Touchez le menu <span class="pwa-key">⋮</span> en haut à droite.', 'Choisissez <strong>« Installer l\'application »</strong> (ou « Ajouter à l\'écran d\'accueil »), puis confirmez.'];
}
if (isMac && isSafari) {
return ['Dans la barre de menus, cliquez sur <strong>Fichier</strong> (ou sur le bouton ' + SHARE + ').',
'Choisissez <strong>« Ajouter au Dock »</strong>, puis <strong>« Ajouter »</strong> (macOS Sonoma ou plus récent).',
'Version plus ancienne de macOS : ouvrez le Dashboard dans <strong>Chrome</strong> ou <strong>Edge</strong> pour l\'installer.'];
}
if (isFirefox) {
return ['Firefox sur ordinateur ne permet pas d\'installer d\'application web.',
'Ouvrez le Dashboard dans <strong>Chrome</strong>, <strong>Edge</strong> ou <strong>Safari</strong> (Mac) puis cliquez à nouveau sur « Installer l\'application ».'];
}
if (isEdge) {
return ['Cliquez sur le menu <span class="pwa-key">…</span> en haut à droite.',
'Choisissez <strong>« Applications »</strong> puis <strong>« Installer ce site en tant qu\'application »</strong>.'];
}
return ['Cliquez sur l\'icône d\'installation <span class="pwa-key">⊕</span> à droite de la barre d\'adresse,',
'ou ouvrez le menu <span class="pwa-key">⋮</span> → <strong>« Caster, enregistrer et partager »</strong> → <strong>« Installer la page en tant qu\'application »</strong>.'];
};
var dialog = null;
function showDialog(title, items, plain) {
if (!dialog) {
dialog = document.createElement('dialog');
dialog.className = 'pwa-dialog';
dialog.setAttribute('aria-labelledby', 'pwa-dialog-title');
dialog.addEventListener('click', function (e) { if (e.target === dialog) dialog.close(); });
document.body.appendChild(dialog);
}
dialog.innerHTML =
'<div class="pwa-dialog__head"><img src="../assets/img/app-192.png" alt="" width="48" height="48">' +
'<div><h2 id="pwa-dialog-title">' + title + '</h2><p>Accès direct au Dashboard, comme une application.</p></div></div>' +
(plain ? '<p class="pwa-dialog__text">' + items.join('') + '</p>' : '<ol class="pwa-dialog__steps">' + items.map(function (s) { return '<li>' + s + '</li>'; }).join('') + '</ol>') +
'<div class="pwa-dialog__actions"><button type="button" class="btn btn--primary" data-pwa-close>Compris</button></div>';
dialog.querySelector('[data-pwa-close]').addEventListener('click', function () { dialog.close(); });
if (typeof dialog.showModal === 'function') dialog.showModal(); else dialog.setAttribute('open', '');
}
buttons.forEach(function (button) {
button.addEventListener('click', function () {
if (deferred) {
var prompt = deferred;
deferred = null;   // la fenêtre du navigateur ne peut servir qu'une fois
prompt.prompt();
return;   // refus : rien de plus (le bouton reste disponible)
}
showDialog('Installer GTC Dashboard', steps());
});
});
})();
